import React, { useState, useCallback } from 'react'
import { View, Text, TouchableOpacity, Dimensions, FlatList } from 'react-native'

import { useContexState } from '../../hooks/context';
import { styles } from './styles';

const keyExtractor = useCallback(
    (item) => {
        const [sd, setSd] = useState()
        item.id.toString()
    }, []
);


export function ShoppingCart() {
    const {
        shoppingCartItem,
        setShoppingCartItem,
        paymentValue,
        setPaymentValue,
        shoppingCartActive,
        setShoppingCartActive
    } = useContexState();

    //const numberValue = [122, 3785, 9873, 3122, 45, 453, 3455, 776, 2235, 2343, 56, 358, 109, 122, 3785, 9873, 3122, 45, 453, 3455, 776, 2235, 2343, 56, 358, 109]

    const result = []

    for (let i = 0; i < shoppingCartItem.length; i++) {
        result.push({ id: i, number: shoppingCartItem[i] })
    };



    const numberItem = useCallback(
        ({ item }) => <Text style={[styles.listText]}>
            {(`0000${item.number}`).slice(-4)}
        </Text>, []
    );

    const conta = shoppingCartItem.length * 19.99;
    const arredondado = parseFloat(conta.toFixed(2));
    const price = arredondado.toString().replace('.', ',');


    return (shoppingCartActive ? <>
        <TouchableOpacity onPress={() => {
            setShoppingCartActive(false)
        }} style={{
            position: 'absolute',
            alignItems: 'center',
            justifyContent: 'center',
            minWidth: Dimensions.get('window').width,
            minHeight: Dimensions.get('window').height
        }} />

        <View style={styles.container} >
            <Text style={{ color: '#fff', fontSize: 20, textAlign: 'center', marginVertical: 6 }}>{`${shoppingCartItem.length} POR APENAS${"\n"}R$ ${price}`}</Text>
            <FlatList
                data={result}
                keyExtractor={keyExtractor}
                numColumns={4}
                renderItem={numberItem}
            />

            <TouchableOpacity style={{
                backgroundColor: '#26A744', borderRadius: 15, width: 230, padding: 10, marginVertical: 15
            }} >
                <Text style={{ color: '#fff', fontSize: 30, textAlign: 'center' }}>Pagar</Text>
            </TouchableOpacity>
        </View>

    </> : null
    );
};

